from typing import List

def minCost(n: int, cost: List[List[int]]) -> int:
    # 核心邏輯：將對應的房屋合併處理 (i 與 n-1-i)
    # 因為它們不能相同顏色，且相鄰限制與遠端限制結合。
    # 我們只需處理前 n/2 個位置。
    # dp[i][c1][c2] 表示到第 i 間房，第 i 房顏色為 c1，第 n-1-i 房顏色為 c2 的最小代價。

    half = n // 2
    # 初始化：第一對房屋 (0, n-1)
    # 因為它們不能相同顏色，c1 != c2
    dp = [[float('inf')] * 3 for _ in range(3)]
    for c1 in range(3):
        for c2 in range(3):
            if c1 != c2:
                dp[c1][c2] = cost[0][c1] + cost[n-1][c2]

    for i in range(1, half):
        new_dp = [[float('inf')] * 3 for _ in range(3)]
        # 前一個位置的顏色對 (pc1, pc2)
        # 當前位置的顏色對 (c1, c2)
        # 限制：c1 != pc1, c2 != pc2, c1 != c2, 以及如果 i == half-1，則 c1 != c2 (已包含在條件中)
        for c1 in range(3):
            for c2 in range(3):
                if c1 == c2: continue

                res = float('inf')
                for pc1 in range(3):
                    for pc2 in range(3):
                        if c1 != pc1 and c2 != pc2:
                            if dp[pc1][pc2] < res:
                                res = dp[pc1][pc2]

                new_dp[c1][c2] = res + cost[i][c1] + cost[n-1-i][c2]
        dp = new_dp

    # 最後處理中間兩間房的相鄰限制 (half-1, half)
    # 實際上，由於我們是成對處理且 c1 != c2，
    # 當 i = half - 1 時，房屋 index 是 (half-1, n-(half-1)) 即 (half-1, half)
    # 因為它們是相鄰的，c1 != c2 已經由我們的迴圈條件保證了。

    ans = float('inf')
    for r in dp:
        ans = min(ans, min(r))
    return int(ans)

