from typing import List

def maxScore(a: List[int], b: List[int]) -> int:
    # dp[j] will store the maximum score using j elements from a
    # Initialize with -infinity because scores can be negative.
    dp = [float('-inf')] * 5
    dp[0] = 0

    for x in b:
        # Update DP states backwards to ensure we use each element of b at most once
        # and maintain the required index order i_0 < i_1 < i_2 < i_3.
        for j in range(4, 0, -1):
            if dp[j-1] != float('-inf'):
                dp[j] = max(dp[j], dp[j-1] + a[j-1] * x)

    return int(dp[4])
