from typing import List

def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:

    # 建立第一天的轉化圖 (Adjacency List)
    # graph1[start] = {target: rate}
    graph1 = {}
    for i in range(len(pairs1)):
        u, v = pairs1[i]
        r = rates1[i]
        if u not in graph1: graph1[u] = {}
        # 如果存在多條路徑，取最大率 (雖然題目說沒矛盾)
        graph1[u][v] = max(graph1[u].get(v, 0.0), r)

    # 建立第二天的轉化圖
    # graph2[start] = {target: rate}
    graph2 = {}
    for i in range(len(pairs2)):
        u, v = pairs2[i]
        r = rates2[i]
        if u not in graph2: graph2[u] = {}
        graph2[u][v] = max(graph2[u].get(v, 0.0), r)

    # 使用 BFS 或 DFS 找出從 initialCurrency 出發在第一天能獲得的最大比例
    def get_max_rates(start_node: str, graph: dict):
        max_r = {start_node: 1.0}
        stack = [start_node]
        while stack:
            u = stack.pop()
            if u in graph:
                for v, r in graph[u].items():
                    new_rate = max_r[u] * r
                    if new_rate > max_r.get(v, 0.0):
                        max_r[v] = new_rate
                        stack.append(v)
        return max_r

    # 第一天從 initialCurrency 出發的所有結果
    rates_after_day1 = get_max_rates(initialCurrency, graph1)

    # 第二天我們需要的是「從任何貨幣到 initialCurrency」的最大比例
    # 這等同於在第二天的圖中，從 initialCurrency 反向尋找所有點的比例
    # 因為每一條邊 (u -> v) 權重為 r，則反向邊 (v -> u) 權重為 1/r
    graph2_reversed = {}
    for u in graph2:
        for v, r in graph2[u].items():
            if v not in graph2_reversed: graph2_reversed[v] = {}
            graph2_reversed[v][u] = max(graph2_reversed[v].get(u, 0.0), 1.0 / r)

    # 在反向圖中從 initialCurrency 出發，找出所有點到 initialCurrency 的最大比例
    rates_to_initial_day2 = get_max_rates(initialCurrency, graph2_reversed)

    max_final_amount = 0.0

    # 遍歷所有可能的中間貨幣 X
    # 結果 = (Day 1: initial -> X) * (Day 2: X -> initial)
    all_currencies = set(rates_after_day1.keys()) | set(rates_to_initial_day2.keys())

    for curr in all_currencies:
        r1 = rates_after_day1.get(curr, 0.0)
        r2 = rates_to_initial_day2.get(curr, 0.0)
        max_final_amount = max(max_final_amount, r1 * r2)

    return float(max_final_amount)
