    # Relax again for Day 2 graph
    currencies2 = set()
    for u, v in [(p[0], p[1]) for p in pairs2]:
        currencies2.add(u)
        currencies2.add(v)
    currencies2.update(max_amounts_final.keys())

    for _ in range(len(currencies2)):
