from typing import List

def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:
    """
    Calculates the maximum amount of initialCurrency obtainable after two days of conversions.
    The core idea is to find all reachable amounts from initialCurrency on Day 1,
    and then for each reached currency, find the max conversion back to initialCurrency on Day 2.
    """
    def get_max_rates(pairs: List[List[str]], rates: List[float]) -> dict:
        dist = {}
        currencies = set()
        for p in pairs:
            currencies.add(p[0])
            currencies.add(p[1])

        for c in currencies:
            dist[c] = {other: 0.0 for other in currencies}
            dist[c][c] = 1.0

        for p, r in zip(pairs, rates):
            u, v = p
            # Since no contradictions/cycles are guaranteed, we update the rate.
            dist[u][v] = max(dist[u].get(v, 0.0), r)

        curr_list = list(currencies)
        for k in curr_list:
            for i in curr_list:
                for j in curr_list:
                    if dist[i][k] > 0 and dist[k][j] > 0:
                        dist[i][j] = max(dist[i][j], dist[i][k] * dist[k][j])
        return dist

    # Get all currencies involved
    all_currencies = set()
    for p in pairs1:
        all_currencies.add(p[0]); all_currencies.add(p[1])
    for p in pairs2:
        all_currencies.add(p[0]); all_currencies.add(p[1])
    all_currencies.add(initialCurrency)

    # Build the distance matrices for both days
    d1 = {}
    for c in all_currencies:
        d1[c] = {other: 0.0 for other in all_currencies}
        d1[c][c] = 1.0

    temp_d1 = get_max_rates(pairs1, rates1)
    for u in temp_d1:
        for v, r in temp_d1[u].items():
            if v in all_currencies:
                d1[u][v] = max(d1[u][v], r)

    d2 = {}
    for c in all_currencies:
