            # 如果前一個是偶數索引，現在就是奇數索引 (負號)
            if 0 in parities:
                new_s = s - x
                new_p = p * x
                if new_p <= limit:
                    new_states[(new_s, new_p)] = new_states.get((new_s, new_p), set()) | {1}
            # 如果前一個是奇數索引，現在就是偶數索引 (正號)
            if 1 in parities:
                new_s = s + x
                new_p = p * x
                if new_p <= limit:
                    new_states[(new_s, new_p)] = new_states.get((new_s, new_p), set()) | {0}

        # 合併到主 dp 表中
        for state, parities in new_states.items():
