from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(current_alternating_sum, current_product)] = True or similar
    # Since we want to maximize product and the limit is small (5000), 
    # let's use dp[alt_sum][product] as a boolean (can we reach this?)
    # However, alt_sum can be negative. We need an offset or a dictionary.

    # Because nums are small (0-12) and length is up to 150, 
    # but the product limit is only 5000, we can use:
    # dp[alt_sum] = set of possible products
    dp = {0: {1}}

    # To handle alternating sum correctly, we need to know if the next element 
    # will be at an even or odd index in the *subsequence*.
    # This means we need dp[alt_sum][parity] where parity is 0 (even) or 1 (odd).
    # But actually, for a subsequence:
    # index 0 of sub -> +nums[i]
    # index 1 of sub -> -nums[i]
    # index 2 of sub -> +nums[i] ...
    # This depends on how many elements were picked before.

    # dp[(alt_sum, count_parity)] = set of products
    # count_parity: 0 means next element will be added (+), 1 means subtracted (-)
    dp = {(0, 0): {1}}

    for x in nums:
        new_dp = {}
        # Option 1: Don't include x (already in dp)
        for state, products in dp.items():
            if state not in new_dp:
                new_dp[state] = set()
            new_dp[state].update(products)

        # Option 2: Include x
        for (s, parity), products in dp.items():
            new_sum = s + x if parity == 0 else s - x
            new_parity = 1 - parity

            if new_sum not in range(-20000, 20000): # Safety bound for k
                if (new_sum, new_parity) not in new_dp:
                    new_dp[(new_sum, new_parity)] = set()
                for p in products:
                    new_prod = p * x
                    if new_prod <= limit:
                        new_dp[(new_sum, new_parity)].add(new_prod)
        dp = new_dp

    max_p = -1
    # We need to find any subsequence that is non-empty. 
    # The initial state (0,0) with product 1 represents an empty subsequence.
    for (s, parity), products in dp.items():
        if s == k:
            for p in products:
                # Ensure it's not the "empty" subsequence if k=0 and limit >= 1
                # But wait, the problem says non-empty. If nums has a 0, 
                # [0] is valid. If we pick nothing, product is 1 but that's empty.
                # Let's refine: only accept products if they came from at least one x.
                pass

    # Re-evaluating logic: The "empty" subsequence has sum 0 and product 1.
    # If k=0, we must ensure the result isn't from picking nothing.

    # Let's use a more explicit DP to track if a product is reached via non-empty subseq
    # dp[alt_sum][parity] = set of products
    dp = {(0, 0): {None}} # None represents empty

    for x in nums:
        next_dp = {}
        # Copy existing
        for state, prods in dp.items():
            if state not in next_dp: next_dp[state] = set()
            next_dp[state].update(prods)

        # Try adding x to all existing states
        for (s, parity), prods in dp.items():
            new_sum = s + x if parity == 0 else s - x
            new_parity = 1 - parity
            if (new_sum, new_parity) not in next_dp: next_dp[(new_sum, new_parity)] = set()
            for p in prods:
                val = p if p is not None else 1
                new_prod = val * x
                if new_prod <= limit:
                    next_dp[(new_sum, new_parity)].add(new_prod)
        dp = next_dp

    ans = -1
    for (s, parity), prods in dp.items():
        if s == k:
            for p in prods:
                if p is not None: # Ensure non-empty
                    ans = max(ans, p)
    return ans
