import heapq

def resultsArray(queries: List[List[int]], k: int) -> List[int]:
    # 使用最大堆積 (Max-Heap) 來儲存前 k 個最小距離。
    # Python 的 heapq 是最小堆積，所以我們將距離取負號來模擬最大堆積。
    max_heap = []
    results = []

    for x, y in queries:
        dist = abs(x) + abs(y)

        if len(max_heap) < k:
            heapq.heappush(max_heap, -dist)
        else:
            # 如果當前距離比堆積中最大的（即最小的第 k 個）還要小，則替換它
            if dist < -max_heap[0]:
                heapq.heapreplace(max_heap, -dist)

        # 如果堆積數量不足 k，回傳 -1
        if len(max_heap) < k:
            results.append(-1)
        else:
            # 堆積頂端就是第 k 小的距離（因為是最大堆積）
            results.append(-max_heap[0])

    return results
