from typing import List

def maximumSubarrayXor(nums: List[int], queries: List[List[int]]) -> List[int]:
    n = len(nums)
    # scores[i][j] is the XOR score of subarray nums[i..j]
    # The formula derived is: score(i, j) = XOR_{k=0}^{j-i} (nums[i+k] if ((j-i) & k) == k else 0)
    scores = [[0] * n for _ in range(n)]

    # Precompute scores using SOS DP approach for each starting position i
    for i in range(n):
        # We only need to consider lengths up to n-i. Since n <= 2000, max length is < 2048.
        limit = min(n - i, 2048)
        dp = [0] * limit
        for k in range(limit):
            dp[k] = nums[i + k]

        # SOS DP to compute XOR sum over subsets for all masks up to 2047
        # This computes dp[mask] = XOR_{sub \subseteq mask} A[sub]
        for bit in range(11):
            bit_val = 1 << bit
            for mask in range(limit):
                if mask & bit_val:
                    dp[mask] ^= dp[mask ^ bit_val]

        # Populate the scores matrix
        for length in range(n - i):
            if length < limit:
                scores[i][i + length] = dp[length]
            else:
                # This part is technically not reachable given n <= 2000, 
                # but included for completeness.
                pass

    # Let res_matrix[i][j] be the maximum score of a subarray starting at k >= i and ending exactly at j.
    res_matrix = [[0] * n for _ in range(n)]
    for j in range(n):
        current_max = -1
        # We iterate backwards from j to 0 to find the max score of a subarray ending at j
        # that starts at some k >= i.
        for i in range(j, -1, -1):
            if scores[i][j] > current_max:
                current_max = scores[i][j]
            res_matrix[i][j] = current_max

    # final_max[i][j] will store the maximum score of any subarray completely contained in [i, j].
    # A subarray [k, m] is inside [i, j] if i <= k <= m <= j.
    final_max = [[0] * n for _ in range(n)]
    for i in range(n):
        curr = 0
        for j in range(i, n):
            # The max score of any subarray contained in [i, j] is the maximum of:
            # 1. The max score of a subarray ending at j and starting >= i (which is res_matrix[i][j])
            # 2. The max score of any subarray contained strictly within [i, j-1] (which is final_max[i][j-1])
            if j == i:
                final_max[i][j] = scores[i][j]
            else:
                final_max[i][j] = max(final_max[i][j-1], res_matrix[i][j])

    ans = []
    for l, r in queries:
        # If the range is invalid (though constraints say 0 <= l <= r <= n-1)
        if l > r:
            ans.append(0)
        else:
            ans.append(final_max[l][r])
    return ans

