```python
def maxSubstringLength(s: str, k: int):
    if k == 0: return True
    n = len(s)
    total_counts = {}
    for char in s:
        total_counts[char] = total_counts.get(char, 0) + 1

    count = 0
    i = 0
    while i < n - 1:
        current_counts = {}
        j = i
        # 這裡我們只需要找到最小的特殊子字串即可，因為題目要求的是 disjoint (不相交)
        # 且找出一個就滿足條件，繼續往後找。
        while j < n and (j - i + 1 < n):
            char = s[j]
            current_counts[char] = current_counts.get(char, 0) + 1

            # 優化點：只有當該字符剛好達到總次數時，才可能構成特殊子字串
            if current_counts[char] == total_counts[char]:
                # 檢查目前區間內所有字符是否都達到了總次數
                if all(current_counts[c] == total_counts[c] for c in current_counts):
                    count += 1
                    i = j + 1
                    break
            j += 1
        else:
            i += 1

    return count >= k
