```python
def maxSubstringLength(s: str, k: int) -> bool:
    if k == 0:
        return True

    n = len(s)
    first_pos = {}
    last_pos = {}
    for idx, char in enumerate(s):
        if char not in first_pos:
            first_pos[char] = idx
        last_pos[char] = idx

    count = 0
    i = 0
    while i < n - 1:
        curr_max = -1
        visited = set()
        found_j = -1

        # Try to find the smallest special substring starting at current index i
        for j in range(i, n):
            char = s[j]
            if first_pos[char] < i:
                # If a character appears before our start point, 
                # no special substring can start here and include this char.
                break
            if char not in visited:
                visited.add(char)
                curr_max = max(curr_max, last_pos[char])

            # Check if current substring s[i:j+1] is special
            # 1. All characters' first and last occurrences are within [i, j]
            # (The first_pos[char] < i check handles the start bound)
            if j == curr_max:
                # 2. Substring must not be the entire string s
                if j - i + 1 < n:
                    found_j = j
                    break

        if found_j != -1:
            count += 1
            i = found_j + 1
        else:
            # If no special substring starts at i, move to the next character.
            # To optimize and avoid O(N^2), we could potentially jump, 
            # but given N=5*10^4 and k<=26, this greedy search is usually sufficient.
            i += 1

    return count >= k

