from typing import List
import math

def minimumIncrements(nums: List[int], target: List[int]) -> int:
    # 找出每個目標對應的最小操作數 (如果已經是倍數則為0)
    # 因為 target 長度極小 (<=4)，我們可以用 bitmask 或簡單窮舉
    n, m = len(nums), len(target)
    res = float('inf')

    # 預處理：每個 nums[i] 對應的目標狀態 (哪些 target 被滿足)
    # 但因為要「增加」數值，我們直接對每個 nums[i] 計算變成哪個 target 的倍數所需的操作
    # cost[i][j] = 最小操作讓 nums[i] 成為 target[j] 的倍數
    costs = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if nums[i] % target[j] == 0:
                costs[i][j] = 0
            else:
                # 下一個倍數是 ((nums[i] // target[j]) + 1) * target[j]
                next_multiple = (nums[i] // target[j] + 1) * target[j]
                costs[i][j] = next_multiple - nums[i]

    # 因為目標數量極少，我們可以用動態規劃或簡單的匹配。
    # 但題目要求「每個 target 有至少一個倍數」，這是一個最小權重覆蓋問題。
    # 由於 n 很大但 m 很小，我們考慮對每個 target 選出一個 nums[i] 來滿足它。

    # 這裡用簡單的 DP: dp[mask] = 最小操作數滿足 mask 中的 target
    dp = [float('inf')] * (1 << m)
    dp[0] = 0

    # 為了優化，我們只考慮每個 nums[i] 能達到的「最便宜」的目標或組合。
    # 但其實可以直接對每個 nums[i]，嘗試把它變成 target[j] 的倍數。
    for i in range(n):
        for j in range(m):
            c = costs[i][j]
            for mask in range((1 << m) - 1, -1, -1):
                if dp[mask] != float('inf'):
                    new_mask = mask | (1 << j)
                    if dp[new_mask] > dp[mask] + c:
                        dp[new_mask] = dp[mask] + c

    # 修正：上面的 DP 有誤，因為一個 nums[i] 同時可以滿足多個 target。
    # 正確邏輯：對於每個 nums[i]，它變成某個目標 j 的倍數後，可能同時滿足其他 k。
    # 但題目是「增加」，所以 nums[i] 變成了 X，X 必須是 target[j] 的倍數。
    # 如果 X 是 target[j] 的倍數且也是 target[k] 的倍數，則 X 必須是 lcm(target[j], target[k]) 的倍數。

    dp = [float('inf')] * (1 << m)
    dp[0] = 0

    for i in range(n):
        # 預計算這個 nums[i] 變成某個 mask 所需的最小操作
        current_nums_costs = {} # mask -> cost
        for mask in range(1, 1 << m):
            # 這個 mask 需要成為所有 bit 為 1 的 target 的公倍數
            lcm_val = 1
            for j in range(m):
                if (mask >> j) & 1:
                    lcm_val = (lcm_val * target[j]) // math.gcd(lcm_val, target[j])

            if nums[i] % lcm_val == 0:
                current_nums_costs[mask] = 0
            else:
                next_mult = (nums[i] // lcm_val + 1) * lcm_val
                current_nums_costs[mask] = next_mult - nums[i]

        for mask in range((1 << m) - 1, -1, -1):
            if dp[mask] == float('inf'): continue
            for sub_mask, cost in current_nums_costs.items():
                new_mask = mask | sub_mask
                if dp[new_mask] > dp[mask] + cost:
                    dp[new_mask] = dp[mask] + cost

    return dp[(1 << m) - 1]

# 由於上面的 DP 複雜度 O(n * 2^m * m) 可能過慢，考慮簡化：
# 因為 target 長度極小 (<=4)，直接用遞迴+備忘錄處理每個 target 選哪一個 nums[i]。
def minimumIncrements(nums: List[int], target: List[int]) -> int:
    m = len(target)
    n = len(nums)
    # cost[j] = 最小操作數讓某個 nums[i] 滿足 target[j]
    # 但這不對，因為一個 nums[i] 可能同時滿足多個。
    # 正確做法：對每個 nums[i]，計算它變成 target[j] 的倍數所需的 cost_ij。
    # 然後找最小的總和。

    costs = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if nums[i] % target[j] == 0: costs[i][j] = 0
            else: costs[i][j] = (nums[i] // target[j] + 1) * target[j] - nums[i]

    # 因為 m 很小，我們可以用 bitmask DP。
    # dp[mask] 是滿足 mask 中目標的最小代價。
    dp = [float('inf')] * (1 << m)
    dp[0] = 0

    for i in range(n):
        # 為此 nums[i]，預先計算出變成各個 target 的倍數後的 cost 與 mask
        # 注意：一個 nums[i] 變為 X，X 可能同時是多個 target 的倍數。
        # 我們只需要考慮那些「它是某個 target 的倍數」的 X。
        possible_moves = [] # (cost, mask)
        for j in range(m):
            # 如果變成 target[j] 的倍數
            if nums[i] % target[j] == 0:
                mask = 0
                for k in range(m):
                    if nums[i] % target[k] == 0: mask |= (1 << k)
                possible_moves.append((0, mask))
            else:
                X = (nums[i] // target[j] + 1) * target[j]
                mask = 0
                for k in range(m):
                    if X % target[k] == 0: mask |= (1 << k)
                possible_moves.append((X - nums[i], mask))

        # 去重並保留最小 cost 的 mask
        best_moves = {}
        for c, mk in possible_moves:
            if mk not in best_moves or c < best_moves[mk]:
                best_moves[mk] = c

        for mask in range((1 << m) - 1, -1, -1):
            if dp[mask] == float('inf'): continue
            for sub_mask, cost in best_moves.items():
                new_mask = mask | sub_mask
                if dp[new_mask] > dp[mask] + cost:
                    dp[new_mask] = dp[mask] + cost

    return int(dp[(1 << m) - 1])
```
